import{_ as u,a0 as a,w as i,s as d,ao as s,I as p,x as t,a1 as e,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 Ubuntu 14.04 里面配置 chroot 环境 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 14.04 里面配置 chroot 环境 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 14.04 里面配置 chroot 环境 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 14.04 里面配置 chroot 环境 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20150114 How to Configure Chroot Environment in Ubuntu 14.04","title":"如何在 Ubuntu 14.04 里面配置 chroot 环境","tag":"201502","desc":""},"relativePath":"201502/20150114 How to Configure Chroot Environment in Ubuntu 14.04.md","filePath":"[post].md"}'),h={name:"201502/20150114 How to Configure Chroot Environment in Ubuntu 14.04.md"};function c(l,o,b,m,f,g){const r=a("Link");return i(),d("div",null,[o[18]||(o[18]=s(`<h1 id="如何在-ubuntu-14-04-里面配置-chroot-环境" tabindex="-1">如何在 Ubuntu 14.04 里面配置 chroot 环境 <a class="header-anchor" href="#如何在-ubuntu-14-04-里面配置-chroot-环境" aria-label="Permalink to “如何在 Ubuntu 14.04 里面配置 chroot 环境”">​</a></h1><p>你可能会有很多理由想要把一个应用、一个用户或者一个环境与你的 linux 系统隔离开来。不同的操作系统有不同的实现方式，而在 linux 中，一个典型的方式就是 chroot 环境。</p><p>在这份教程中，我会一步一步指导你怎么使用 chroot 命令去配置一个与真实系统分离出来的独立环境。这个功能主要可以用于测试项目，以下这些步骤都在 <strong>Ubuntu 14.04</strong> 虚拟专用服务器(VPS)上执行。</p><p>学会快速搭建一个简单的 chroot 环境是一项非常实用的技能，绝大多数系统管理员都能从中受益。</p><h3 id="chroot-环境" tabindex="-1">Chroot 环境 <a class="header-anchor" href="#chroot-环境" aria-label="Permalink to “Chroot 环境”">​</a></h3><p>一个 chroot 环境就是通过系统调用，将一个本地目录临时变成根目录。一般所说的系统根目录就是挂载点&quot;/&quot;，然而使用 chroot 命令后，你可以使用其它目录作为根目录。</p><p>原则上，任何运行在 chroot 环境内的应用都不能访问系统中其他信息（LCTT译注：使用 chroot 把一个目录变成根目录，在里面运行的应用只能访问本目录内的文件，无法访问到目录外的文件。然而，运行在 chroot 环境的应用可以通过 sysfs 文件系统访问到环境外的信息，所以，这里有个“原则上”的修饰语）。</p><h3 id="chroot-环境的用处" tabindex="-1">Chroot 环境的用处 <a class="header-anchor" href="#chroot-环境的用处" aria-label="Permalink to “Chroot 环境的用处”">​</a></h3><blockquote><ul><li><p>测试一个不稳定的应用服务不会影响到整个主机系统。</p></li><li><p>就算使用 root 权限做了些不当的操作，把 chroot 环境搞得一塌糊涂，也不会影响到主机系统。</p></li><li><p>可以在你的系统中运行另外一个操作系统。</p></li></ul></blockquote><p>举个例子，你可以在 chroot 环境中编译、安装、测试软件，而不去动真实的系统。你也可以<strong>在64位环境下使用 chroot 创建一个32位环境，然后运行一个32位的程序</strong>（LCTT泽注：如果你的真实环境是32位的，那就不能 chroot 一个64位的环境了）。</p><p>但是为了安全考虑，chroot 环境为非特权用户设立了非常严格的限制，而不是提供完整的安全策略。如果你需要的是有完善的安全策略的隔离方案，可以考虑下 LXC、Docker、vservers等等。</p><h3 id="debootstrap-和-schroot" tabindex="-1">Debootstrap 和 Schroot <a class="header-anchor" href="#debootstrap-和-schroot" aria-label="Permalink to “Debootstrap 和 Schroot”">​</a></h3><p>使用 chroot 环境需要安装 <strong>debootstrap</strong> 和 <strong>schroot</strong>，这两个软件都在 Ubuntu 的镜像源中。其中 schroot 用于创建 chroot 环境。</p><p><strong>Debootstrap</strong> 可以让你通过镜像源安装任何 Debian（或基于 Debian 的）系统，装好的系统会包含最基本的命令。</p><p><strong>Schroot</strong> 命令允许用户使用相同的机制去创建 chroot 环境，但在访问 chroot 环境时会做些权限检查，并且会允许用户做些额外的自动设置，比如挂载一些文件系统。</p><p>在 Ubuntu 14.04 LTS 上，我们可以通过两步来实现这个功能：</p><h3 id="_1-安装软件包" tabindex="-1">1. 安装软件包 <a class="header-anchor" href="#_1-安装软件包" aria-label="Permalink to “1. 安装软件包”">​</a></h3><p>第一步，在Ubuntu 14.04 LTS 主机系统上安装 debootstrap 和 schroot：</p><pre><code>$ sudo apt-get install debootstrap 
$ sudo apt-get install schroot
</code></pre><h3 id="_2-配置-schroot" tabindex="-1">2. 配置 Schroot <a class="header-anchor" href="#_2-配置-schroot" aria-label="Permalink to “2. 配置 Schroot”">​</a></h3><p>现在我们有工具在手，需要指定一个目录作为我们的 chroot 环境。这里创建一个目录先：</p><pre><code>sudo mkdir /linoxide
</code></pre><p>编辑 schroot 的配置文件：</p><pre><code>sudo nano /etc/schroot/schroot.conf
</code></pre><p>再提醒一下，我们现在是在 Ubuntu 14.04 LTS 系统上。如果我们想测试一个软件包能不能在 Ubuntu 13.10（代号是“Saucy Salamander”） 上运行，就可以在配置文件中添加下面的内容：</p><pre><code>[saucy]
description=Ubuntu Saucy
location=/linoxide
priority=3
users=arun
root-groups=root
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/schroot-config.png" alt=""></p><p>根据你的系统要求，调整上面的配置信息。</p><h3 id="_3-使用-debootstrap-安装32位-ubuntu-系统" tabindex="-1">3. 使用 debootstrap 安装32位 Ubuntu 系统 <a class="header-anchor" href="#_3-使用-debootstrap-安装32位-ubuntu-系统" aria-label="Permalink to “3. 使用 debootstrap 安装32位 Ubuntu 系统”">​</a></h3><p>Debootstrap 命令会在你的 <strong>chroot 环境</strong>里面下载安装一个最小系统。只要你能访问镜像源，你就可以安装任何基于 Debian 的系统版本。</p><p>前面我们已经创建了 <strong>/linoxide</strong> 目录用于放置 chroot 环境，现在我们可以在这个目录里面运行 debootstrap 了：</p><pre><code>cd /linoxide
sudo debootstrap --variant=buildd --arch amd64 saucy /linoxide/ http://archive.ubuntu.com/ubuntu/
sudo chroot /linoxide /debootstrap/debootstrap --second-stage
</code></pre>`,32)),p("p",null,[o[2]||(o[2]=t("你可以将 --arch 的参数换成 i386 或其他架构，只要存在这种架构的镜像源。你也可以把镜像源 ",-1)),e(r,{href:"http://archive.ubuntu.com/ubuntu/"},{default:n(()=>[...o[0]||(o[0]=[t("http://archive.ubuntu.com/ubuntu/",-1)])]),_:1}),o[3]||(o[3]=t(" 换成离你最近的镜像源，具体可参考 ",-1)),e(r,{href:"https://launchpad.net/ubuntu/+archivemirrors"},{default:n(()=>[...o[1]||(o[1]=[t("Ubuntu 官方镜像主页",-1)])]),_:1}),o[4]||(o[4]=t("。",-1))]),o[19]||(o[19]=s(`<p><strong>注意：如果你是在64位系统中创建32位系统，你需要在上面第3行命令中加入 --foreign 选项，就像下面的命令：</strong></p><pre><code>sudo debootstrap --variant=buildd --foreign --arch i386 saucy /linoxide/ http://archive.ubuntu.com/ubuntu/
</code></pre><p>下载需要一段时间，看你网络带宽性能。最小系统大概有500M。</p><h3 id="_4-完成-chroot-环境" tabindex="-1">4. 完成 chroot 环境 <a class="header-anchor" href="#_4-完成-chroot-环境" aria-label="Permalink to “4. 完成 chroot 环境”">​</a></h3><p>安装完系统后，我们需要做一些收尾工作，确保系统运行正常。首先，保证主机的 fstab 程序能意识到 chroot 环境的存在：</p><pre><code>sudo nano /etc/fstab
</code></pre><p>在文件最后面添加下面的配置：</p><pre><code>proc /linoxide/proc proc defaults 0 0
sysfs /linoxide/sys sysfs defaults 0 0
</code></pre><p>保存并关闭文件。</p><p>挂载一些文件系统到 chroot 环境：</p><pre><code>$ sudo mount proc /linoxide/proc -t proc
$ sudo mount sysfs /linoxide/sys -t sysfs
</code></pre><p>复制 /etc/hosts 文件到 chroot 环境，这样 chroot 环境就可以使用网络了：</p><pre><code>$ sudo cp /etc/hosts /linoxide/etc/hosts
</code></pre><p>最后使用 schroot -l 命令列出系统上所有的 chroot 环境：</p><pre><code>$ schroot -l
</code></pre><p>使用下面的命令进入 chroot 环境：</p><pre><code>$ sudo chroot /linoxide/ /bin/bash
</code></pre><p>测试安装的版本：</p><pre><code># lsb_release -a
# uname -a
</code></pre><p>为了在 chroot 环境中使用图形界面，你需要设置 DISPLAY 环境变量：</p><pre><code>$ DISPLAY=:0.0 ./apps
</code></pre><p>目前为止，我已经成功地在 Ubuntu 14.04 LTS 上安装了 Ubuntu 13.10。</p><p>退出 chroot 环境：</p><pre><code># exit
</code></pre><p>清理一下，卸载文件系统：</p><pre><code>$ sudo umount /test/proc
$ sudo umount /test/sys
</code></pre><hr>`,27)),p("p",null,[o[6]||(o[6]=t("via: ",-1)),e(r,{href:"http://linoxide.com/ubuntu-how-to/configure-chroot-environment-ubuntu-14-04/"},{default:n(()=>[...o[5]||(o[5]=[t("http://linoxide.com/ubuntu-how-to/configure-chroot-environment-ubuntu-14-04/",-1)])]),_:1})]),p("p",null,[o[10]||(o[10]=t("作者：",-1)),e(r,{href:"http://linoxide.com/author/arunp/"},{default:n(()=>[...o[7]||(o[7]=[t("Arun Pyasi",-1)])]),_:1}),o[11]||(o[11]=t(" 译者：",-1)),e(r,{href:"https://github.com/bazz2"},{default:n(()=>[...o[8]||(o[8]=[t("bazz2",-1)])]),_:1}),o[12]||(o[12]=t(" 校对：",-1)),e(r,{href:"https://github.com/wxy"},{default:n(()=>[...o[9]||(o[9]=[t("wxy",-1)])]),_:1})]),p("p",null,[o[15]||(o[15]=t("本文由 ",-1)),e(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...o[13]||(o[13]=[t("LCTT",-1)])]),_:1}),o[16]||(o[16]=t(" 原创翻译，",-1)),e(r,{href:"http://linux.cn/"},{default:n(()=>[...o[14]||(o[14]=[t("Linux中国",-1)])]),_:1}),o[17]||(o[17]=t(" 荣誉推出",-1))])])}const _=u(h,[["render",c]]);export{C as __pageData,_ as default};
